import{_ as a,o as n,c as s,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"操盘手训练","description":"","frontmatter":{},"headers":[],"relativePath":"features/training.md","filePath":"features/training.md","lastUpdated":null}'),r={name:"features/training.md"};function e(l,t,i,d,p,h){return n(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="操盘手训练" tabindex="-1">操盘手训练 <a class="header-anchor" href="#操盘手训练" aria-label="Permalink to &quot;操盘手训练&quot;">​</a></h1><p>操盘手训练不是平台里的一个独立菜单，而是一种由 <strong>历史回放 + 模拟盘手工交易</strong> 组合而成的<strong>复盘训练</strong>玩法：把历史行情像录像一样重新播放，你在&quot;身临其境&quot;的行情中用手工下单的方式做交易，练盘感、练纪律、验证交易思路 —— 全程零风险，且可以用远比真实时间快的速度完成。</p><h2 id="为什么用回放做训练" tabindex="-1">为什么用回放做训练 <a class="header-anchor" href="#为什么用回放做训练" aria-label="Permalink to &quot;为什么用回放做训练&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统复盘</th><th>Northstar 回放训练</th></tr></thead><tbody><tr><td>看着静态K线图&quot;脑补&quot;当时会怎么操作</td><td>行情逐TICK真实重演，<strong>不知道后面走势</strong>，如同身临其境</td></tr><tr><td>只能想想，无法验证</td><td>真实下单、真实撮合，盈亏立现</td></tr><tr><td>一天行情要花一天复盘</td><td>可调速，一天的行情几分钟过完</td></tr><tr><td>无法统计训练成果</td><td>账户绩效自动统计胜率、盈亏曲线</td></tr></tbody></table><h2 id="训练环境搭建-一次性-约-3-分钟" tabindex="-1">训练环境搭建（一次性，约 3 分钟） <a class="header-anchor" href="#训练环境搭建-一次性-约-3-分钟" aria-label="Permalink to &quot;训练环境搭建（一次性，约 3 分钟）&quot;">​</a></h2><h3 id="第-1-步-创建回放行情网关" tabindex="-1">第 1 步：创建回放行情网关 <a class="header-anchor" href="#第-1-步-创建回放行情网关" aria-label="Permalink to &quot;第 1 步：创建回放行情网关&quot;">​</a></h3><p><strong>网关管理 → 新建</strong>：</p><ul><li>网关用途：<strong>行情</strong></li><li>网关渠道：<strong>PLAYBACK</strong></li><li>订阅合约：选择你想训练的品种</li><li><strong>网关配置</strong>：用&quot;近一周/近三月/近一年/近两年&quot;快捷按钮设定训练区间；回放精度建议先选<strong>低</strong>（加载快）</li></ul><p>详见 <a href="/features/playback#第一步-创建回放网关">历史回放</a>。</p><h3 id="第-2-步-创建训练用模拟账户" tabindex="-1">第 2 步：创建训练用模拟账户 <a class="header-anchor" href="#第-2-步-创建训练用模拟账户" aria-label="Permalink to &quot;第 2 步：创建训练用模拟账户&quot;">​</a></h3><p>再次 <strong>新建</strong>：</p><ul><li>网关用途：<strong>交易</strong></li><li>网关渠道：<strong>SIM</strong></li><li>行情网关：<strong>绑定 PLAYBACK 回放网关</strong>（关键！让模拟账户撮合回放行情）</li></ul><p>创建后将该网关<strong>连线</strong>，并通过卡片菜单 <strong>出入金</strong> 注入训练资金（例如 10 万）。</p><h3 id="第-3-步-打开训练界面" tabindex="-1">第 3 步：打开训练界面 <a class="header-anchor" href="#第-3-步-打开训练界面" aria-label="Permalink to &quot;第 3 步：打开训练界面&quot;">​</a></h3><p>进入 <strong>交易中心 → 多图同列</strong>（<code>Alt+9</code>）：</p><ul><li>数据类型：<strong>回放</strong></li><li>图表数：建议 2~4 图</li><li>周期：建议一个主周期（如 5m）+ 一个方向周期（如 30m）</li><li>品种：选择训练品种 → 点<strong>刷新</strong></li></ul><p>展开底部<strong>交易面板</strong>，交易账户选择刚才的 SIM 训练账户。</p><p>训练环境就绪，界面布局如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────┐</span></span>
<span class="line"><span>│  多图同列：回放行情K线（多周期） │</span></span>
<span class="line"><span>│  （头部：回放控制按钮）          │</span></span>
<span class="line"><span>├────────────────────────────────┤</span></span>
<span class="line"><span>│  交易面板：账户 | 合约 | 手数    │</span></span>
<span class="line"><span>│  [买开] [卖开] [平仓]            │</span></span>
<span class="line"><span>│  持仓 | 挂单 | 计划 | 委托 | 成交 │</span></span>
<span class="line"><span>└────────────────────────────────┘</span></span></code></pre></div><h2 id="开始训练" tabindex="-1">开始训练 <a class="header-anchor" href="#开始训练" aria-label="Permalink to &quot;开始训练&quot;">​</a></h2><h3 id="基本训练循环" tabindex="-1">基本训练循环 <a class="header-anchor" href="#基本训练循环" aria-label="Permalink to &quot;基本训练循环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alt+Q（预加载）→ Alt+Q（开始回放）→ 观察行情 → 交易面板下单</span></span>
<span class="line"><span>→ Alt+W（逐K推进，一根K线一根K线地走）→ 持仓管理 → 平仓</span></span>
<span class="line"><span>→ 重复 → Alt+Q 暂停 → 查看账户绩效复盘</span></span></code></pre></div><h3 id="训练技巧" tabindex="-1">训练技巧 <a class="header-anchor" href="#训练技巧" aria-label="Permalink to &quot;训练技巧&quot;">​</a></h3><ol><li><p><strong>逐K回放是最核心的训练模式</strong> 按 <code>Alt+W</code> 一根K线一根K线地推进，每根K线出现后问自己：&quot;现在该怎么办？&quot; —— 开仓？持有？止损？做出决策并执行，再看下一根K线验证。这完美模拟了实盘决策过程。</p><ul><li>用&quot;逐K步长&quot;下拉匹配你的交易周期（5m 交易者选 5m 步长）。</li></ul></li><li><p><strong>用时间线跳转专攻经典行情</strong> 回放暂停后（预加载完成状态），直接修改&quot;当前时间线&quot;跳到某个历史时点 —— 例如反复练习某次暴涨暴跌行情的开仓时机。</p></li><li><p><strong>用画线交易练交易计划</strong> K线图上右键 → 画线交易 → 交易计划：画出入场线、止损线、止盈线，系统会显示盈亏比并要求确认。训练&quot;先有计划、后有交易&quot;的纪律，计划触线自动执行，杜绝临时起意。</p></li><li><p><strong>用调速练反应</strong> 把回放速度调快，模拟行情快速波动时的决策压力；遇到关键位置再调慢或暂停思考。</p></li><li><p><strong>练完必复盘</strong> 交易面板点&quot;账户绩效&quot;图标：</p><ul><li><strong>交易记录</strong>：逐笔回看每笔交易的开平仓位置（配合&quot;显示历史持仓线&quot;，直接在K线图上看买卖点）；</li><li><strong>交易统计</strong>：盈亏分布、交易笔数、盈亏合计；</li><li><strong>盈亏曲线</strong>：资金曲线是训练成果最直观的体现。</li></ul></li></ol><h3 id="重置再练" tabindex="-1">重置再练 <a class="header-anchor" href="#重置再练" aria-label="Permalink to &quot;重置再练&quot;">​</a></h3><p><code>Alt+S</code> 状态重置后回放回到起点，可以换一段区间（修改回放网关的日期配置），或者重新挑战同一段行情 —— 同一个品种同一段行情，多练几遍，对比几次的绩效曲线，检验自己是否真的&quot;学会了&quot;。</p><h2 id="推荐训练计划" tabindex="-1">推荐训练计划 <a class="header-anchor" href="#推荐训练计划" aria-label="Permalink to &quot;推荐训练计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>做法</th></tr></thead><tbody><tr><td>入门</td><td>熟悉操作</td><td>近一周数据 + 低精度 + 逐K回放，熟悉下单、平仓、撤单</td></tr><tr><td>进阶</td><td>建立交易系统</td><td>固定一套进出场规则，在近三月数据上严格执行，统计胜率与盈亏比</td></tr><tr><td>强化</td><td>压力训练</td><td>调快回放速度，或选择剧烈波动的行情段，训练纪律执行力</td></tr><tr><td>检验</td><td>盲测</td><td>换一段从未看过的区间（近一年/近两年），不看结果完整做完，最后看绩效</td></tr></tbody></table><h2 id="从手工训练到程序化" tabindex="-1">从手工训练到程序化 <a class="header-anchor" href="#从手工训练到程序化" aria-label="Permalink to &quot;从手工训练到程序化&quot;">​</a></h2><p>当你在训练中沉淀出稳定的交易规则后，可以把它写成交易策略（Java 类），创建用途为&quot;回测&quot;的模组在同样的历史区间上自动运行 —— 对比&quot;手工训练的绩效&quot;与&quot;程序化执行的绩效&quot;，检验规则的客观性与自己的情绪损耗。详见 <a href="/features/auto-trading">程序化交易</a>。</p>`,30)])])}const g=a(r,[["render",e]]);export{c as __pageData,g as default};
